#!/usr/bin/env python3
"""Builds CORPUS-QUALITY/high_risk_record_review.csv (C8 / WS-E high-risk sample review).

Usage (from the repository root):
    python legal_knowledge/audit_work/C8-SOURCES/CORPUS-QUALITY/work/build_hr.py [REPO_ROOT]
        [--sample work/sample_selection.csv] [--out-dir CORPUS-QUALITY] [--check]

Inputs: REPO_ROOT/legal_knowledge/curated_originals/{knowledge_base/v0.9/records_658.jsonl,
case_law/v0.9/cases_53.jsonl} (read only) and the committed sample selection. Every quoted
proposition is asserted to occur verbatim in the record. --check regenerates in memory and
compares byte-for-byte with the committed CSV (exit 1 on difference); nothing is written.
The row content is hand-entered review data: --check proves determinism, not correctness.
Dependency cells were re-checked against the registers after review RC-01/RC-07 (see
C8-SOURCES/review/DISPOSITIONS_44fd72d6.md).
"""
import argparse,csv,io,json,os,sys
HERE=os.path.dirname(os.path.abspath(__file__))
ap=argparse.ArgumentParser(description=__doc__,formatter_class=argparse.RawDescriptionHelpFormatter)
ap.add_argument('repo',nargs='?',default='.')
ap.add_argument('--sample',default=os.path.join(HERE,'sample_selection.csv'))
ap.add_argument('--out-dir',default=os.path.dirname(HERE))
ap.add_argument('--check',action='store_true')
A=ap.parse_args()
B=os.path.join(A.repo,'legal_knowledge','curated_originals')+os.sep
def _jl(p):
    with open(p,encoding='utf-8') as f: return {json.loads(l)['id']:json.loads(l) for l in f if l.strip()}
KB=_jl(B+'knowledge_base/v0.9/records_658.jsonl')
CS=_jl(B+'case_law/v0.9/cases_53.jsonl')
with open(A.sample,newline='',encoding='utf-8') as _f: sel={r['record_id']:r for r in csv.DictReader(_f)}
A37C="Commencement: the India Code compilation prints 'w.e.f. 6-9-1992' only at ss.75-76, s.127 and Chapter XVI (e47a4265 pp.27, 36, 48), not at every provision Act 37/1992 amends; it is a compilation statement (the assent date). The Act prints no commencement clause (held Gazette scan f11d443e, pp.1-4); commencement NOT_STATED_PENDING_ADVICE (AQ-05; amendment_commencement_matrix D-AMC-AA-08-*)"
R23="No amendment to r.23 located: 31 instruments examined 1960-2022, none amends r.23 (R23-VERIFY-01 amendment_search_2026-11-22.csv; C5-CF-U-01; ARMY-RULES-CHAIN-01 chronology r.23 'NO AMENDMENT LOCATED'). S.R.O. 6(E)/2022 amends r.16A(4) only (R23-VERIFY-01 amendment_chain_r23.csv, amends r.23 = NO). Gaps not closed: E-7 of 17-06-1960 (AR-001), S.R.O. 258/2002 (AR-030), anything after 06-06-2022 (AR-036, not searched), and the unopened search hints AR-012, AR-013, AR-015 (HINT_ONLY, TO_CHECK). r.23(3) wording CONFLICTING, reserved (C-01/U-01)"
AA='Army Act India Code compilation sha256 e47a4265813e95b491a24926428ed306cfeaae9013e7edb928cefef6e69a7c08 (GOVERNMENT_COMPILATION; no Gazette copy of 1950 Act held)'
AR='Army Rules India Code compilation sha256 48f52219121bf74d070bc832e4573f2f512b239e0a0441ba96b1daca2983a727 (GOVERNMENT_COMPILATION)'
AFT='AFT Act India Code compilation sha256 665863d1abb802f7488eb75f776946e30e72ccec16962da8e2b3ee8f2e023e3b'
F=["sample_no","record_id","record_type","domain","selection_basis","asserted_proposition_quote","supporting_source_refs","verification_against_held_authority","amendment_or_date_dependencies","inconsistent_linked_records","remaining_evidence_gap_class","prior_findings","c8_assessment","proposal_ref"]
rows=[]
def r(rid,dom,quote,refs,ver,dep,inc,gap,prior,assess,prop,manual=None):
    rec=KB.get(rid) or CS.get(rid)
    src=(rec.get('body','')+' '+rec.get('references','')) if rid in KB else ' '.join(str(v) for v in rec.values())
    assert quote in src, (rid,quote)
    s=sel.get(rid)
    basis=manual or (f"deterministic: score={s['score']} prior_P0P1={s['prior_P0P1']} missing_evidence_rows={s['missing_evidence_rows']}" if s and s['score'] else "deterministic: case with negative/qualifying later treatment in WS-B case_relations")
    rows.append(dict(zip(F,[len(rows)+1,rid,'KB' if rid in KB else 'CASE',dom,basis,quote,refs,ver,dep,inc,gap,prior,assess,prop])))
